import{_ as l,o as e,c as i,O as t}from"./chunks/framework.ac0f74f3.js";const r="/assets/yl1.d2726e2a.png",o="/assets/yl2.64d31181.png",p="/assets/yl3.a2334af0.png",h="/assets/yl4.3d7415f0.png",q=JSON.parse('{"title":"原料列表","description":"","frontmatter":{},"headers":[],"relativePath":"技术管理/原料列表.md","filePath":"技术管理/原料列表.md"}'),s={name:"技术管理/原料列表.md"};function n(u,a,d,c,_,b){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="原料列表" tabindex="-1">原料列表 <a class="header-anchor" href="#原料列表" aria-label="Permalink to &quot;原料列表&quot;">​</a></h1><blockquote><p>原料列表位于技术管理板块，可添加原料系列、在系列中新增的原料支持，复制，编辑，删除 等操作.</p></blockquote><h4 id="_1-新增-编辑原料系列" tabindex="-1">1.新增/编辑原料系列 <a class="header-anchor" href="#_1-新增-编辑原料系列" aria-label="Permalink to &quot;1.新增/编辑原料系列&quot;">​</a></h4><ul><li><p>默认显示所有系列，鼠标悬浮在系列上面可点击＋新增系列</p><p>-新增的系列可再加子系列，子系列也可以往下面延申</p><p>-如果该系列下有原料数据，就无法删除，没有数据的 可删除</p><p>-新增的系列可编辑和拖拽调整位置</p><p>-分类树支持拖拽调整宽度</p></li></ul><h4 id="_2-新增原料" tabindex="-1">2.新增原料 <a class="header-anchor" href="#_2-新增原料" aria-label="Permalink to &quot;2.新增原料&quot;">​</a></h4><ul><li><p>点击新增原料按钮添加原料</p><p>-在新增原料之前需选择对应的系列（放置的位置）</p><p>-新增的原料名称/规格可以重复</p><p>-如果在创建原料时状态选择了停用，那这个原料就不可用</p></li></ul><h4 id="_3-表头设置" tabindex="-1">3.表头设置 <a class="header-anchor" href="#_3-表头设置" aria-label="Permalink to &quot;3.表头设置&quot;">​</a></h4><ul><li>点击表头设置图标可更改表头字段的显示/隐藏</li></ul><p><img src="'+r+'" alt="如图所示"></p><h4 id="_4-删除功能" tabindex="-1">4.删除功能 <a class="header-anchor" href="#_4-删除功能" aria-label="Permalink to &quot;4.删除功能&quot;">​</a></h4><ul><li>需要删除时先在编辑中将状态改为停用才能删除</li><li>已经进行合同签章的原料不允许进行删除</li></ul><h4 id="_5-批量删除" tabindex="-1">5.批量删除 <a class="header-anchor" href="#_5-批量删除" aria-label="Permalink to &quot;5.批量删除&quot;">​</a></h4><ul><li><p>勾选需要删除的内容，点击批量删除按钮即可删除</p><p>-需要删除时先在编辑中将状态改为停用才能删除</p><p>-有BOM的情况下是无法删除的，需要解除在进行删除</p></li></ul><h4 id="_6-编辑功能" tabindex="-1">6.编辑功能 <a class="header-anchor" href="#_6-编辑功能" aria-label="Permalink to &quot;6.编辑功能&quot;">​</a></h4><ul><li>可在原有新增的原料上进行编辑修改</li></ul><h4 id="_7-批量编辑" tabindex="-1">7.批量编辑 <a class="header-anchor" href="#_7-批量编辑" aria-label="Permalink to &quot;7.批量编辑&quot;">​</a></h4><ul><li><p>先勾选需要批量编辑的产品，点击批量编辑按钮即可进行编辑</p><p>-点击可维护检验准则（支持添加多个检验项目）</p></li></ul><h4 id="_8-复制功能" tabindex="-1">8.复制功能 <a class="header-anchor" href="#_8-复制功能" aria-label="Permalink to &quot;8.复制功能&quot;">​</a></h4><ul><li>可在这个原料的基础上去复制一个相同的零件出来，能够复制全部信息</li></ul><p><img src="'+o+'" alt="如图所示"></p><h4 id="_9-维护检验准则" tabindex="-1">9.维护检验准则 <a class="header-anchor" href="#_9-维护检验准则" aria-label="Permalink to &quot;9.维护检验准则&quot;">​</a></h4><ul><li><p>添加检验项目（支持添加多个检验项目）</p><p>-检验项目来源于检验项目列表</p><p>-检验项目在品质部质检时起到重要关键</p></li></ul><h4 id="_10-更改记录" tabindex="-1">10.更改记录 <a class="header-anchor" href="#_10-更改记录" aria-label="Permalink to &quot;10.更改记录&quot;">​</a></h4><ul><li>显示更改人，更改时间</li><li>会记录以下更改：原料编号修改，原料名称修改，原料规格修改，原料状态修改</li></ul><h4 id="_11-批量导出" tabindex="-1">11.批量导出 <a class="header-anchor" href="#_11-批量导出" aria-label="Permalink to &quot;11.批量导出&quot;">​</a></h4><ul><li><p>点击导出按钮分为两种导出样式</p><p>-先勾选需导出的内容，点击导出按钮选择第一个选项</p><p>-点击导出按钮，选择第二个选项，手动输入导入1~N条</p></li></ul><h4 id="_12-备注" tabindex="-1">12.备注 <a class="header-anchor" href="#_12-备注" aria-label="Permalink to &quot;12.备注&quot;">​</a></h4><ul><li>点击对应的备注字段添加备注</li></ul><p><img src="'+p+'" alt="如图所示"></p><h4 id="_13-更新" tabindex="-1">13.更新 <a class="header-anchor" href="#_13-更新" aria-label="Permalink to &quot;13.更新&quot;">​</a></h4><ul><li>将导出的产品编辑完成后，点击更新按钮上传文件即可</li></ul><h4 id="_14-导入" tabindex="-1">14.导入 <a class="header-anchor" href="#_14-导入" aria-label="Permalink to &quot;14.导入&quot;">​</a></h4><ul><li><p>点击批量导入，先下载模板（注意下载的模板只适用于批量导入原料里面上传的模板)</p></li><li><p>点开下载的模板进行编辑（编辑时请阅读表格上面的提示文案，以防导入时出现错误，从而无法导入）</p><p>-模板中的检验项目名称就是技术部检验项目列表中所添加的检验项</p></li><li><p>点击或者拖拽所保存的模板（只有在原料的批量导入中下载的模板才能上传，其他无效）进行上传</p></li><li><p>上传成功会弹出显示上传的数据，可选择性导入或者一键导入（如果无法导入，请滑动到页面最后，查看提示信息，可能存在编辑时出现的错误，需从新更改再次上传）</p></li></ul><p><img src="'+h+'" alt="如图所示"></p>',34)])])}const f=l(s,[["render",n]]);export{q as __pageData,f as default};
